package ua.energykits.app;
import android.app.*; import android.os.*; import android.widget.*; import android.view.*; import android.graphics.Color; import android.content.*; import android.net.Uri; import org.json.*; import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root, results, fieldHost; EditText inv,bat,ip,bp,iv,bv,ah,bms,watts; JSONArray kits=new JSONArray();
 
 class EquipmentArt extends View {
 final int kind; android.graphics.Bitmap photo; final android.graphics.Paint p=new android.graphics.Paint(3);
 EquipmentArt(int k){super(MainActivity.this);kind=k;try(java.io.InputStream in=getAssets().open(new String[]{"inverter.jpg","battery.jpg","solar_house.jpg"}[k])){photo=android.graphics.BitmapFactory.decodeStream(in);}catch(java.io.IOException ignored){}setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}
 void rect(android.graphics.Canvas c,int color,float x,float y,float w,float h,float radius){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,radius,radius,p);}
 void poly(android.graphics.Canvas c,int color,float... xy){p.setColor(color);android.graphics.Path q=new android.graphics.Path();q.moveTo(xy[0],xy[1]);for(int i=2;i<xy.length;i+=2)q.lineTo(xy[i],xy[i+1]);q.close();c.drawPath(q,p);}
 protected void onDraw(android.graphics.Canvas c){super.onDraw(c);if(photo!=null){float ratio=Math.min(getWidth()/(float)photo.getWidth(),getHeight()/(float)photo.getHeight());float w=photo.getWidth()*ratio,h=photo.getHeight()*ratio; c.drawBitmap(photo,null,new android.graphics.RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2),p);return;}float scale=Math.min(getWidth()/100f,getHeight()/120f);c.save();c.translate((getWidth()-100*scale)/2,(getHeight()-120*scale)/2);c.scale(scale,scale);
 p.setColor(0x5522cfff);c.drawOval(2,18,98,110,p);
 if(kind==0){rect(c,0xff8294aa,13,12,76,99,8);rect(c,0xffedf5ff,9,9,75,97,8);rect(c,0xffc4d4e6,14,15,65,5,2);rect(c,0xff101b26,27,68,39,25,4);rect(c,0xff53c967,33,73,27,9,2);for(int i=0;i<3;i++)rect(c,0xffaab8c9,33+i*10,85,5,3,1);rect(c,0xff26394e,21,106,9,7,2);rect(c,0xff26394e,65,106,9,7,2);}
 else if(kind==1){rect(c,0xff101820,8,40,85,68,5);poly(c,0xff526276,8,40,20,28,94,28,93,40);rect(c,0xffd53030,22,23,12,9,2);rect(c,0xffc4d4e6,68,23,12,9,2);rect(c,0xff25374c,13,45,75,57,4);p.setColor(Color.WHITE);p.setTextSize(16);p.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);p.setTextAlign(android.graphics.Paint.Align.CENTER);c.drawText("LiFePO4",50,76,p);p.setTextAlign(android.graphics.Paint.Align.LEFT);}
 else {rect(c,0xffad713b,19,53,70,53,2);poly(c,0xff25394c,7,56,50,14,98,56);poly(c,0xff1768ad,14,51,48,19,74,43,41,51);for(int i=0;i<3;i++)rect(c,0xffffd479,26+i*20,65,12,17,1);rect(c,0xff563a26,49,87,14,19,1);}
 c.restore();}
 }
 LinearLayout section(int kind){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);EquipmentArt image=new EquipmentArt(kind);row.addView(image,new LinearLayout.LayoutParams(dp(82),dp(128)));LinearLayout fields=new LinearLayout(this);fields.setOrientation(LinearLayout.VERTICAL);row.addView(fields,new LinearLayout.LayoutParams(0,-2,1));space(row);return fields;}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 android.graphics.drawable.GradientDrawable gloss(int top,int bottom){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{top,bottom});d.setCornerRadius(dp(12));d.setStroke(dp(1),0xff45d9ff);return d;}
 void space(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));root.addView(v,p);}
 EditText field(String hint,int type){EditText e=new EditText(this);e.setHint(hint);e.setInputType(type);e.setTextColor(Color.WHITE);e.setHintTextColor(0xffc6ddf5);e.setTextSize(16);e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setBackground(gloss(0xff102e59,0xff071b3d));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.setMargins(0,dp(3),0,dp(3));fieldHost.addView(e,fp);return e;}
 void button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextColor(Color.WHITE);b.setTextSize(15);b.setTypeface(null,android.graphics.Typeface.BOLD);b.setMinHeight(dp(48));int top=0xff008dff,bottom=0xff003779;if(name.equals("Додати комплект")){top=0xff39b900;bottom=0xff126000;}if(name.equals("Вихід")){top=0xffff3939;bottom=0xff990000;}b.setBackgroundTintList(null);b.setBackground(gloss(top,bottom));space(b);b.setOnClickListener(v->action.run());}
 double num(EditText e){double x=Double.parseDouble(e.getText().toString().replace(',','.'));if((Double.isNaN(x)||Double.isInfinite(x))||x<=0)throw new IllegalArgumentException();return x;}
 public void onCreate(Bundle b){super.onCreate(b);try{kits=new JSONArray(getPreferences(Context.MODE_PRIVATE).getString("kits","[]"));}catch(Exception ignored){}
 ScrollView s=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(16),dp(12),dp(16));root.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xff030e2c,0xff064e9b,0xff031330}));s.setFillViewport(true);getWindow().setStatusBarColor(0xff030e2c);getWindow().setNavigationBarColor(0xff030e2c);s.addView(root);setContentView(s);
 TextView title=new TextView(this);title.setText("⚡ Підбір енергокомплектів");title.setTextSize(22);title.setTextColor(Color.WHITE);title.setTypeface(null,android.graphics.Typeface.BOLD_ITALIC);title.setGravity(Gravity.CENTER);title.setPadding(dp(8),dp(12),dp(8),dp(12));title.setBackground(gloss(0xff006bd0,0xff041b50));space(title);
 fieldHost=section(0);inv=field("Модель інвертора",android.text.InputType.TYPE_CLASS_TEXT);ip=field("Ціна інвертора, грн",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);iv=field("Номінальна напруга системи, В",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);watts=field("Потужність інвертора, Вт",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
 button("Знайти інвертор в інтернеті",()->search(inv.getText().toString()+" інвертор ціна Україна"));
 fieldHost=section(1);bat=field("Модель акумулятора",android.text.InputType.TYPE_CLASS_TEXT);bp=field("Ціна АКБ, грн",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);bv=field("Номінальна напруга АКБ, В",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);ah=field("Ємність АКБ, А·год",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);bms=field("Тривалий струм BMS, А",android.text.InputType.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
 button("Знайти акумулятор в інтернеті",()->search(bat.getText().toString()+" LiFePO4 акумулятор ціна Україна"));
 button("Додати комплект",()->add());button("Новий вибір",()->{for(EditText e:new EditText[]{inv,bat,ip,bp,iv,bv,ah,bms,watts})e.setText("");});
 EquipmentArt house=new EquipmentArt(2);root.addView(house,new LinearLayout.LayoutParams(-1,dp(100)));results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);render();button("Вихід",()->{save();finish();});}
 void search(String q){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/search?q="+Uri.encode(q))));}catch(Exception e){Toast.makeText(this,"Браузер недоступний",Toast.LENGTH_SHORT).show();}}
 void add(){try{double v=num(iv),a=num(bv),p=num(watts),current=num(bms);if(inv.getText().toString().trim().isEmpty()||bat.getText().toString().trim().isEmpty())throw new IllegalArgumentException();JSONObject k=new JSONObject();k.put("name",inv.getText()+" + "+bat.getText());k.put("price",num(ip)+num(bp));k.put("energy",a*num(ah)/1000);k.put("note",Math.abs(v-a)/v>0.1?"Напруга не відповідає":p>v*0.9*current*0.9?"BMS може обмежувати потужність":"Попередня оцінка струму достатня; перевірте паспорт і протоколи");kits.put(k);save();render();}catch(Exception e){Toast.makeText(this,"Заповніть усі поля коректними значеннями",Toast.LENGTH_SHORT).show();}}
 void save(){getPreferences(Context.MODE_PRIVATE).edit().putString("kits",kits.toString()).apply();}
 void render(){results.removeAllViews();ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<kits.length();i++)list.add(kits.optJSONObject(i));Collections.sort(list,(a,b)->Double.compare(a.optDouble("price"),b.optDouble("price")));for(JSONObject k:list){TextView t=new TextView(this);t.setText(k.optString("name")+"\n"+k.optDouble("price")+" грн | "+k.optDouble("energy")+" кВт·год\n"+k.optString("note")+"\nЦіна введена вручну");t.setTextSize(18);t.setTextColor(Color.WHITE);t.setBackground(gloss(0xff153d70,0xff081c3c));t.setPadding(12,18,12,18);results.addView(t);}}
}